<script>document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('.site-dropdown-toggle').forEach(button=>button.addEventListener('click',event=>{event.stopPropagation();const menu=button.closest('.site-dropdown');document.querySelectorAll('.site-dropdown.open').forEach(item=>{if(item!==menu){item.classList.remove('open');item.querySelector('.site-dropdown-toggle')?.setAttribute('aria-expanded','false')}});const open=menu.classList.toggle('open');button.setAttribute('aria-expanded',String(open))}));document.addEventListener('click',()=>document.querySelectorAll('.site-dropdown.open').forEach(item=>{item.classList.remove('open');item.querySelector('.site-dropdown-toggle')?.setAttribute('aria-expanded','false')}))})</script>
